public class ZonedDateTimeField_add_TriageGen0Test {

    private ZonedDateTimeField zonedDateTimeField;
    private org.joda.time.chrono.ZonedField iField;
    private org.joda.time.chrono.ZoneField iZone;

    @Before
    public void setUp() throws Exception {
        zonedDateTimeField = mock(ZonedDateTimeField.class);
        iField = mock(org.joda.time.chrono.ZonedField.class);
        iZone = mock(org.joda.time.chrono.ZoneField.class);

        // Since ZonedDateTimeField is an inner class of ZonedChronology, 
        // we use reflection to set the private fields for testing the logic provided.
        setField(zonedDateTimeField, "iField", iField);
        setField(zonedDateTimeField, "iZone", iZone);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private void setBooleanField(Object target, String fieldName, boolean value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testAdd_WithITimeFieldTrue() throws Exception {
        // Arrange
        setBooleanField(zonedDateTimeField, "iTimeField", true);
        long instant = 1000L;
        long value = 500L;
        int offset = 100L;

        // We need to mock getOffsetToAdd which is a method in the same class.
        // Since we are testing the logic of the provided snippet, 
        // we assume getOffsetToAdd is available. 
        // In a real scenario, if it's a method in the class, we might need a spy.
        ZonedDateTimeField spyField = org.mockito.Mockito.spy(zonedDateTimeField);
        when(spyField.getOffsetToAdd(instant)).thenReturn(offset);
        when(iField.add(instant + offset, value)).thenReturn(1600L); // (1000 + 100) + 500 = 1600

        // Act
        long result = spyField.add(instant, value);

        // Assert
        // result = localInstant - offset => 1600 - 100 = 1500
        assertEquals(1500L, result);
    }

    @Test
    public void testAdd_WithITimeFieldFalse() throws Exception {
        // Arrange
        setBooleanField(zonedDateTimeField, "iTimeField", false);
        long instant = 1000L;
        long value = 500L;
        long localInstantAfterConversion = 2000L;
        long localInstantAfterAdd = 2500L;
        long finalUtcInstant = 1500L;

        when(iZone.convertUTCToLocal(instant)).thenReturn(localInstantAfterConversion);
        when(iField.add(localInstantAfterConversion, value)).thenReturn(localInstantAfterAdd);
        when(iZone.convertLocalToUTC(localInstantAfterAdd, false)).thenReturn(finalUtcInstant);

        // Act
        long result = zonedDateTimeField.add(instant, value);

        // Assert
        assertEquals(finalUtcInstant, result);
    }
}
